 public static async Task<string> Run(){AntColony.UI.SimulationPause.UserSpeed(0);var c=AntColony.Core.CommanderRoster.Instance.Commanders.First(x=>x&&x.IsColonyMember);var p=c.GetComponent<MeshyNativeMotionPlayer>();var v=c.GetComponent<AntVisual>();var f=BindingFlags.NonPublic|BindingFlags.Instance;typeof(AntVisual).GetField("playedClip",f).SetValue(v,"Tool_Till");typeof(AntVisual).GetField("heldTool",f).SetValue(v,"Tool_Hoe_Stone");p.Configure(Resources.Load<MeshyNativeLibrary>("MeshyNative/Library"));p.PreviewMotion="Charged_Axe_Chop";p.PreviewPhase=.1666667f;await Task.Delay(200);var cam=Camera.main;UnityEngine.Object.FindAnyObjectByType<AntColony.Camera.IsometricCameraController>().enabled=false;cam.orthographicSize=1.7f;var focus=c.Position+Vector3.up*.6f;cam.transform.position=focus+new Vector3(-3,2,3);cam.transform.LookAt(focus);ScreenCapture.CaptureScreenshot("work/motion-actions-1113/hoe-source.png");var bones=p.NativeModel.GetComponentsInChildren<Transform>();return string.Join("\n",bones.Where(t=>t.name.Contains("Hand")&&!t.name.Contains("HandM")&&!t.name.Contains("HandI")&&!t.name.Contains("HandR")&&!t.name.Contains("HandP")&&!t.name.Contains("HandT")).Select(t=>t.name+" "+(t.position-c.Position)));}
